// The word table, the language the screen is drawn in, and what a formatter is given. Nothing
// else lives there and nothing else leaves this file.
import { LOCALES, LANGUAGES, WORDS, tr, trn, setLang, getLang, localeTag, browserLang } from "./words";
const API = process.env.REACT_APP_API_URL || "https://ocsa-api-production.up.railway.app";
// Every call to the API leaves through here. It says the language the screen is drawn in twice: as
// locale= on the address, which a signed-in call is answered in ahead of the language on the
// person's account, and as Accept-Language, which the API reads for a call made signed out. Both are
// read when the call is made from the same place tr() reads it, so a language switched on screen is
// the language of the next call. The API answers its refusals, notices, pick lists and checklist
// items in that language. An address that already names a language keeps its own. The body and
// every other header are the caller's, untouched.
function withLocale(url) {
  const s = String(url);
  if (/[?&]locale=/.test(s)) return s;
  return s + (s.indexOf("?") >= 0 ? "&" : "?") + "locale=" + getLang();
}
function apiRequest(url, init = {}) {
  return fetch(withLocale(url), { ...init, headers: { ...init.headers, "Accept-Language": getLang() } });
}
async function apiUpload(file, bucket, token) {
  const ext = file.name.split(".").pop().toLowerCase();
  const res = await apiRequest(API + "/api/uploads?bucket=" + encodeURIComponent(bucket) + "&ext=" + encodeURIComponent(ext), {
    method: "POST",
    headers: { "Authorization": "Bearer " + token, "Content-Type": file.type },
    body: file,
  });
  if (res.status === 401) { window.dispatchEvent(new Event("ocsa-session-expired")); throw new Error(tr("Session expired")); }
  if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error(e.error || tr("Upload failed")); }
  return res.json();
}
// attachment; filename="<code>-<id>.pdf" -> <code>-<id>.pdf. Anything unreadable falls back.
const filenameFrom = (header, fallback) => {
  const m = /filename\*?=(?:UTF-8'')?"?([^";]+)"?/i.exec(String(header || ""));
  let name = "";
  if (m) { try { name = decodeURIComponent(m[1].trim()); } catch (e) { name = m[1].trim(); } }
  return name || fallback;
};
// A response that is a file rather than JSON. The token and the refusal handling are apiFetch's, so a
// 401 signs out and a refusal arrives with the words the API sent and its status.
async function apiDownload(path, token, fallbackName) {
  const r = await apiRequest(API + path, { headers: { "Authorization": "Bearer " + token } });
  if (r.status === 401) { window.dispatchEvent(new Event("ocsa-session-expired")); const err = new Error(tr("Session expired")); err.status = 401; throw err; }
  if (!r.ok) { const e = await r.json().catch(() => ({})); const err = new Error(e.error || tr("Request failed")); err.status = r.status; err.code = e.code; err.body = e; throw err; }
  return { blob: await r.blob(), filename: filenameFrom(r.headers.get("Content-Disposition"), fallbackName || "report.pdf") };
}
// A file the API makes, fetched through apiDownload and handed to the browser to save under the name
// the API gives it, or the fallback when that name cannot be read.
async function saveDownload(path, token, fallbackName) {
  const f = await apiDownload(path, token, fallbackName);
  const url = URL.createObjectURL(f.blob);
  const a = document.createElement("a");
  a.href = url; a.download = f.filename;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 5000);
}
// A request whose body is files rather than JSON, sent as multipart form data. The token and the
// refusal handling are apiFetch's, so a 401 signs out and a refusal arrives with the words the API
// sent, its status and its code.
async function apiMultipart(path, token, formData) {
  const r = await apiRequest(API + path, { method: "POST", headers: { "Authorization": "Bearer " + token }, body: formData });
  if (r.status === 401) { window.dispatchEvent(new Event("ocsa-session-expired")); const err = new Error(tr("Session expired")); err.status = 401; throw err; }
  if (!r.ok) { const e = await r.json().catch(() => ({})); const err = new Error(e.error || tr("Request failed")); err.status = r.status; err.code = e.code; err.body = e; throw err; }
  return r.json();
}
// A 409 schedule.clearanceMissing (Step 211) is announced as well as thrown, whichever screen sent the
// call, and the shell draws it with the person's name and a way to their clearances by the userId the
// refusal carries.
async function apiFetch(path, opts = {}) {
  const h = { "Content-Type": "application/json", ...opts.headers };
  if (opts.token) h["Authorization"] = "Bearer " + opts.token;
  const r = await apiRequest(API + path, { ...opts, headers: h, body: opts.body ? JSON.stringify(opts.body) : undefined });
  if (r.status === 401) { window.dispatchEvent(new Event("ocsa-session-expired")); const err = new Error(tr("Session expired")); err.status = 401; throw err; }
  if (!r.ok) {
    const e = await r.json().catch(() => ({})); const err = new Error(e.error || tr("Request failed")); err.status = r.status; err.code = e.code; err.body = e;
    if (e && e.code === "schedule.clearanceMissing") { try { window.dispatchEvent(new CustomEvent("ocsa-clearance-missing", { detail: { missing: e.missing, keys: e.keys, userId: e.userId == null ? null : e.userId, body: opts.body || null } })); } catch (x) { /* a browser with no CustomEvent shows the toast alone */ } }
    throw err;
  }
  return r.json();
}
// An answer the API writes as it goes. The request is apiFetch's, through apiRequest, so the address,
// the token, the body and Accept-Language are what apiFetch would send, and a refusal before the
// stream opens is thrown the way apiFetch throws it. Past that each event is handed to onEvent as it
// is read, with its data: meta, delta, reset and done. An error event is thrown as a refusal with its
// own words and status. A stream that breaks or ends before done throws with dropped set, since the
// API finishes and stores the answer whatever happens to the connection. Events are split at blank
// lines and read with fetch, since EventSource cannot send a POST.
async function apiStream(path, opts = {}, onEvent) {
  const h = { "Content-Type": "application/json", ...opts.headers };
  if (opts.token) h["Authorization"] = "Bearer " + opts.token;
  const refusal = (status, e) => {
    if (status === 401) { window.dispatchEvent(new Event("ocsa-session-expired")); const err = new Error(tr("Session expired")); err.status = 401; return err; }
    const err = new Error((e && e.error) || tr("Request failed")); err.status = status; err.code = e && e.code; err.body = e; return err;
  };
  const r = await apiRequest(API + path, { ...opts, headers: h, body: opts.body ? JSON.stringify(opts.body) : undefined });
  if (!r.ok) throw refusal(r.status, await r.json().catch(() => ({})));
  if ((r.headers.get("Content-Type") || "").indexOf("text/event-stream") < 0) { onEvent("done", await r.json()); return; }
  const reader = r.body.getReader();
  const decoder = new TextDecoder();
  let buf = "";
  for (;;) {
    let chunk;
    try { chunk = await reader.read(); } catch (e) { e.dropped = true; throw e; }
    if (chunk.done) break;
    buf += decoder.decode(chunk.value, { stream: true });
    for (let at = buf.search(/\r?\n\r?\n/); at >= 0; at = buf.search(/\r?\n\r?\n/)) {
      let event = "", data = "";
      buf.slice(0, at).split(/\r?\n/).forEach(line => {
        if (line.startsWith("event:")) event = line.slice(6).trim();
        else if (line.startsWith("data:")) data += (data ? "\n" : "") + line.slice(5).replace(/^ /, "");
      });
      buf = buf.slice(at).replace(/^\r?\n\r?\n/, "");
      if (!event) continue;
      let d = {};
      try { d = data ? JSON.parse(data) : {}; } catch { d = {}; }
      if (event === "error") { reader.cancel().catch(() => {}); throw refusal(Number(d.status) || 500, d); }
      onEvent(event, d);
      if (event === "done") { reader.cancel().catch(() => {}); return; }
    }
  }
  const err = new Error(tr("Request failed")); err.dropped = true; throw err;
}
// The signed-in session, persisted so a refresh or a restored tab does not land on the login card.
// A stored token is never trusted on its own: AdminDashboard verifies it with GET /api/auth/me first.
const AUTH_KEY = "ocsa_auth";
const readAuth = () => { try { const raw = localStorage.getItem(AUTH_KEY); if (!raw) return null; const d = JSON.parse(raw); return d && typeof d.token === "string" && d.token ? d : null; } catch { return null; } };
const writeAuth = (token, user) => { try { localStorage.setItem(AUTH_KEY, JSON.stringify({ token, user })); } catch {} };
const clearAuth = () => { try { localStorage.removeItem(AUTH_KEY); } catch {} };
// Every page id the render switch knows. The URL hash is checked against this list before it is used.
const PAGE_IDS = ["overview", "staff", "hr", "sites", "assigned", "schedule", "operations", "issues", "supplies", "vendors", "services", "chat", "reports", "inspections", "marketplace", "forms", "settings", "cases", "help", "announcements", "help-insights", "form-builder", "quotes", "clearances"];
// The pages an admin opens and nobody else. A person who reaches one of these another way is told
